const KEY='numiquest-v1';const fresh=()=>({version:1,lang:'vi',name:'Explorer',xp:0,selected:'VN',pieces:{},history:[],mistakes:[],mastery:{},best:0});let state=fresh();try{state={...state,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{}let lang=state.lang==='en'?'en':'vi',view='home',session=null,tick=null,raf=null,afterModal=null;const t=(vi,en)=>lang==='vi'?vi:en;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
