function track(q,correct,elapsed,mode){if(mode!=='review'){let m=state.mastery[q.skill]||[];m.push(correct?1:0);state.mastery[q.skill]=m.slice(-10)}if(!correct&&!state.mistakes.some(x=>x.id===q.id))state.mistakes.push(q);save()}
function startQuiz(){stop();view='quiz';session={kind:'practice',questions:Array.from({length:config.count},()=>generate()),index:0,results:[],done:false};showQuiz()}
function showQuiz(){cancelQuizAdvance();const s=session;s.answered=false;if(s.index>=s.questions.length){finishPractice();return}const q=s.questions[s.index];$('#app').innerHTML=`<div class="narrow"><div class="row"><span class="tag">${t('Câu','Question')} ${s.index+1}/${s.questions.length}</span><strong class="timer" id="clock"></strong></div><div class="progress"><div style="width:${s.index/s.questions.length*100}%"></div></div><div class="card"><div class="question">${esc(q.q)} = ?</div><div class="answers">${q.options.map((o,i)=>`<button class="answer" data-answer="${i}"><small>${'ABCD'[i]}</small>${esc(o)}</button>`).join('')}</div><p id="feedback" class="muted" role="status"></p></div></div>`;s.started=performance.now();s.extra=false;startClock(config.seconds,()=>{modal(`<h2>⏳ ${t('Hết giờ rồi','Time is up')}</h2><p>${t('Thêm thời gian hoặc bỏ qua để ôn lại trong game.','Add time or skip to review in the game.')}</p><div class="actions"><button id="extra">+${config.seconds}s</button><button id="skip">${t('Bỏ qua','Skip')}</button></div>`);$('#closeModal').hidden=true;$('#extra').onclick=()=>{s.extra=true;$('#closeModal').hidden=false;$('#modal').close();startClock(config.seconds,()=>timeoutAgain())};$('#skip').onclick=()=>{$('#closeModal').hidden=false;$('#modal').close();answerQuiz(null)}});$$('[data-answer]').forEach(b=>b.onclick=()=>answerQuiz(q.options[+b.dataset.answer],q.id));translate()}
