function startClock(seconds,cb){clearInterval(tick);let end=performance.now()+seconds*1000;function update(){let left=Math.max(0,(end-performance.now())/1000);if($('#clock'))$('#clock').textContent=left.toFixed(1)+'s';if(left<=0){clearInterval(tick);cb()}}update();tick=setInterval(update,100)}
function answerQuiz(ans,questionId){if(view!=='quiz'||!session||session.done||session.answered)return;const s=session,q=s.questions[s.index];if(questionId&&questionId!==q.id)return;s.answered=true;clearInterval(tick);cancelQuizAdvance();const correct=ans===q.answer,elapsed=(performance.now()-s.started)/1000;s.results.push({correct,elapsed,extra:s.extra});track(q,correct,elapsed,'practice');s.index++;showQuiz()}
function finishPractice(){session.done=true;let s=session,n=s.results.filter(x=>x.correct).length;state.history.push({date:new Date().toISOString(),mode:'practice',correct:n,total:s.results.length,time:avg(s.results.map(x=>x.elapsed)),extra:s.results.filter(x=>x.extra).length});state.history=state.history.slice(-200);state.xp+=n*3;if(!state.mistakes.length&&n===s.results.length)award(1);save();$('#app').innerHTML=`<div class="narrow card"><div class="trophy">🌟</div><h1>${t('Một bước tiến mới!','Another step forward!')}</h1><p>${n}/${s.results.length} ${t('câu đúng lần đầu','correct on the first try')} · ${avg(s.results.map(x=>x.elapsed)).toFixed(1)}s/${t('câu','question')}</p><p>${state.mistakes.length?t('Cùng ôn lại câu sai trong chuyến phiêu lưu nhé.','Review your mistakes on an adventure.'):t('Em đã làm đúng tất cả! Nhận mảnh khám phá và chọn bài mới nhé.','All correct! Collect your discovery piece and choose a new challenge.')}</p>${state.mistakes.length?`<button class="primary" onclick="startReview()">${t('Ôn câu sai bằng game','Review mistakes in the game')} →</button>`:`<div class="notice">${t('Đã nhận 1 mảnh khám phá. Không có câu sai cần ôn.','1 discovery piece earned. No mistakes to review.')}</div><div class="actions"><button class="primary" onclick="nav('setup')">${t('Luyện lượt mới','Practice again')}</button><button onclick="nav('atlas')">${t('Xem hộ chiếu','Open passport')}</button></div>`}</div>`;translate()}
function hint(q){const op=q.skill.split(':')[1];return q.explanation+'\n'+(op==='+'?t('Tách số thành chục và đơn vị, cộng từng phần rồi ghép lại.','Split numbers into tens and ones, add the parts, then combine.'):op==='-'?t('Trừ từng phần; có thể đếm từ số nhỏ lên số lớn để tìm khoảng cách.','Subtract in parts, or count up from the smaller number.'):op==='*'?t('Tách một thừa số thành các phần nhỏ, nhân rồi cộng các kết quả.','Split a factor into smaller parts, multiply, then add.'):t('Tìm số nhân với số chia để được số bị chia. Nếu có dư, phần dư nhỏ hơn số chia.','Find the factor that matches the dividend. A remainder must be smaller than the divisor.'))}
