startReview=function(){if(!state.mistakes.length){toast(t('Không có câu sai cần ôn. Em làm tốt lắm!','No mistakes to review. Well done!'));return}stop();view='garden';document.body.dataset.view='garden';$('#app').classList.remove('game-layout');const qs=state.mistakes.map(q=>({...q,options:[...q.options]}));garden={questions:qs,offset:0,perPage:Math.min(6,qs.length),lives:3,done:new Set(),used:new Set(),active:null,deadline:0,remaining:{},busy:false};session={kind:'garden',done:false};gardenSelection=null;gardenRender();if(!state.gardenIntroSeen){clearInterval(gardenTimer);modal(`<div class="intro-animal">${animal('bunny')}</div><h2>${t('Giúp hoa tìm đúng chậu nhé!','Help each flower find its pot!')}</h2><p>${t('Mỗi chậu là một phép tính em cần ôn. Hoa mang đáp án. Kéo hoa vào chậu đúng — hoa sẽ nở! Em cũng có thể kéo chậu sang hoa.','Each pot holds a question to review. Flowers carry answers. Drag a flower to its matching pot and watch it bloom! You can also drag a pot to a flower.')}</p><div class="notice">${t('Trên điện thoại: chạm hoa, rồi chạm chậu để ghép. Nhìn viền xanh để biết câu đang tính giờ.','On a phone: tap a flower, then a pot. The green outline shows the question being timed.')}</div>`,()=>{state.gardenIntroSeen=true;save();gardenActivate(garden.questions[garden.offset].id)})}else gardenActivate(garden.questions[garden.offset].id);translate()};
function gardenPage(){return garden.questions.slice(garden.offset,garden.offset+garden.perPage)}
function gardenRender(){clearInterval(gardenTimer);gardenSelection=null;const qs=gardenPage();if(!garden.answers||garden.pageOffset!==garden.offset){garden.answers=shuffle(qs.map(q=>({id:q.id,answer:q.answer})));garden.pageOffset=garden.offset}$('#app').innerHTML=`<div class="garden-shell"><div class="garden-heading"><div><span class="eyebrow">${t('ÔN CÂU SAI · VƯỜN HOA ĐÁP ÁN','MISTAKE REVIEW · THE ANSWER GARDEN')}</span><h1>${t('Ghép đúng, hoa nở.','Match it. Watch it bloom.')}</h1></div><div class="garden-buddy">${animal(buddy())}</div></div><div class="garden-toolbar"><span class="garden-count">${t('Đã ôn','Reviewed')} <b>${garden.done.size}/${garden.questions.length}</b></span><span class="garden-lives" id="gardenLives" aria-label="${garden.lives} ${t('mạng','lives')}">${Array.from({length:3},(_,i)=>`<span class="heart ${i<garden.lives?'full':''}">♡</span>`).join('')}</span><span id="gardenClock" class="timer"></span></div><div class="progress"><div style="width:${garden.done.size/garden.questions.length*100}%"></div></div><p class="garden-instruction">${t('Kéo hoa vào chậu đúng. Hoặc chạm một bên, rồi chạm bên kia.','Drag a flower to its matching pot. Or tap one side, then the other.')}</p><div class="garden-board"><div class="garden-column pots-column"><div class="garden-column-label"><span>01</span>${t('Chậu phép tính','Question pots')}</div>${qs.map((q,i)=>`<button class="garden-item pot-item ${garden.done.has(q.id)?'matched':''}" data-match-kind="pot" data-match-id="${q.id}" aria-label="${esc(q.q)}" ${garden.done.has(q.id)?'disabled':''}><span class="pot-scene">${garden.done.has(q.id)?gardenFlower(true,i):''}${gardenPot()}</span><span class="pot-equation">${esc(q.q)}<small>${garden.done.has(q.id)?'= '+esc(q.answer):'= ?'}</small></span>${garden.done.has(q.id)?'<span class="match-check">✓</span>':''}</button>`).join('')}</div><div class="garden-column flowers-column"><div class="garden-column-label"><span>02</span>${t('Hoa đáp án','Answer flowers')}</div>${garden.answers.map((a,i)=>`<button class="garden-item flower-item ${garden.used.has(a.id)?'used':''}" data-match-kind="flower" data-match-id="${a.id}" aria-label="${t('Đáp án','Answer')} ${esc(a.answer)}" ${garden.used.has(a.id)?'disabled':''}>${gardenFlower(false,i)}<span class="flower-answer">${esc(a.answer)}</span><span class="drag-handle" aria-hidden="true">⠿</span></button>`).join('')}</div></div><div class="garden-footer"><span>${t('Ghép sai hoặc hết giờ: mất 1 mạng. Hết mạng sẽ có hướng dẫn.','A wrong match or timeout costs a life. Guidance appears when lives run out.')}</span><button id="gardenHelp">${t('Xem cách chơi','How to play')}</button></div></div>`;$$('[data-match-kind]').forEach(card=>{if(card.disabled)return;card.onpointerdown=e=>gardenPointer(e,card);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();gardenChoose(card.dataset.matchKind,card.dataset.matchId)}}});$('#gardenHelp').onclick=()=>{gardenPause();modal(`<h2>${t('Cùng ghép hoa nhé','Let’s match the flowers')}</h2><p>${t('Chọn một phép tính bên trái, tìm kết quả ở bông hoa bên phải. Kéo hai thẻ lại với nhau, hoặc chạm lần lượt vào chúng. Chỉ những câu sai của em xuất hiện ở đây.','Choose a question on the left and find its answer on the right. Drag the two cards together or tap them in turn. Only your mistakes appear here.')}</p>`,()=>gardenResume())};translate()}
function gardenPause(){clearInterval(gardenTimer);if(garden?.active&&garden.deadline)garden.remaining[garden.active]=Math.max(.1,(garden.deadline-performance.now())/1000);garden.deadline=0}
function gardenResume(){if(view!=='garden'||!garden||session.done)return;let q=garden.questions.find(q=>q.id===garden.active&&!garden.done.has(q.id))||gardenPage().find(q=>!garden.done.has(q.id));if(q)gardenActivate(q.id)}
function gardenActivate(id){if(view!=='garden'||garden.busy||garden.done.has(id))return;gardenPause();garden.active=id;const q=garden.questions.find(q=>q.id===id);const budget=garden.remaining[id]??q.config?.seconds??15;garden.deadline=performance.now()+budget*1000;$$('.pot-item').forEach(b=>b.classList.toggle('timed',b.dataset.matchId===id));function update(){if(view!=='garden'){clearInterval(gardenTimer);return}const seconds=Math.max(0,(garden.deadline-performance.now())/1000);if($('#gardenClock'))$('#gardenClock').textContent=seconds.toFixed(1)+'s';if(seconds<=0){clearInterval(gardenTimer);gardenError(q,true)}}update();gardenTimer=setInterval(update,100)}
function gardenChoose(kind,id){if(garden.busy||view!=='garden')return;if(kind==='pot')gardenActivate(id);if(gardenSelection&&gardenSelection.kind!==kind){const potId=kind==='pot'?id:gardenSelection.id,flowerId=kind==='flower'?id:gardenSelection.id;gardenSelection=null;gardenMatch(potId,flowerId);return}gardenSelection={kind,id};$$('[data-match-kind]').forEach(b=>{const selected=b.dataset.matchKind===kind&&b.dataset.matchId===id;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))})}
function gardenPointer(e,card){if(e.button!==0||garden.busy||card.disabled)return;e.preventDefault();const startX=e.clientX,startY=e.clientY;let moving=false;card.setPointerCapture(e.pointerId);card.onpointermove=ev=>{if(Math.hypot(ev.clientX-startX,ev.clientY-startY)>8&&!moving){moving=true;gardenGhost=card.cloneNode(true);gardenGhost.classList.add('garden-ghost');gardenGhost.removeAttribute('data-match-kind');gardenGhost.removeAttribute('data-match-id');gardenGhost.style.width=card.offsetWidth+'px';document.body.append(gardenGhost);card.classList.add('dragging')}if(gardenGhost){gardenGhost.style.left=ev.clientX+'px';gardenGhost.style.top=ev.clientY+'px';$$('.drop-target').forEach(x=>x.classList.remove('drop-target'));const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-match-kind]');if(target&&!target.disabled&&target.dataset.matchKind!==card.dataset.matchKind)target.classList.add('drop-target')}};card.onpointerup=ev=>{card.onpointermove=null;card.onpointerup=null;card.onpointercancel=null;gardenGhost?.remove();gardenGhost=null;card.classList.remove('dragging');$$('.drop-target').forEach(x=>x.classList.remove('drop-target'));if(moving){const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-match-kind]');if(target&&!target.disabled&&target.dataset.matchKind!==card.dataset.matchKind){const pot=card.dataset.matchKind==='pot'?card:target,flower=card.dataset.matchKind==='flower'?card:target;gardenMatch(pot.dataset.matchId,flower.dataset.matchId)}}else gardenChoose(card.dataset.matchKind,card.dataset.matchId)};card.onpointercancel=()=>{gardenGhost?.remove();gardenGhost=null;card.classList.remove('dragging');$$('.drop-target').forEach(x=>x.classList.remove('drop-target'))}}
function gardenMatch(potId,flowerId){if(garden.busy||garden.done.has(potId)||garden.used.has(flowerId))return;const q=garden.questions.find(q=>q.id===potId),flower=garden.answers.find(a=>a.id===flowerId);if(!q||!flower)return;gardenPause();garden.active=potId;if(q.answer!==flower.answer){gardenError(q,false);return}garden.busy=true;chime(true);garden.done.add(potId);garden.used.add(flowerId);state.mistakes=state.mistakes.filter(x=>x.id!==q.id);state.xp+=5;const completedPage=gardenPage().every(x=>garden.done.has(x.id));if(completedPage)award(1);save();const pot=$(`[data-match-kind="pot"][data-match-id="${potId}"]`),bud=$(`[data-match-kind="flower"][data-match-id="${flowerId}"]`);pot.classList.remove('timed','selected');pot.classList.add('matched','bloom-now');pot.disabled=true;pot.querySelector('.pot-scene').insertAdjacentHTML('afterbegin',gardenFlower(true,garden.answers.indexOf(flower)));pot.querySelector('.pot-equation small').textContent='= '+q.answer;pot.insertAdjacentHTML('beforeend','<span class="match-check">✓</span>');bud.classList.add('used');bud.disabled=true;$$('.selected').filter(x=>x.matches('[data-match-kind]')).forEach(x=>x.classList.remove('selected'));$('.garden-count b').textContent=`${garden.done.size}/${garden.questions.length}`;$('.garden-shell .progress>div').style.width=garden.done.size/garden.questions.length*100+'%';setTimeout(()=>{if(view!=='garden')return;garden.busy=false;if(gardenPage().every(x=>garden.done.has(x.id))){garden.offset+=garden.perPage;if(garden.offset>=garden.questions.length){session.done=true;gardenFinish();return}modal(`<h2>${t('Một góc vườn đã nở hoa!','Your little garden is blooming!')}</h2><p>${t('Em nhận 1 mảnh khám phá. Cùng chăm những bông hoa tiếp theo nhé.','You earned a discovery piece. Let’s care for the next flowers.')}</p>`,()=>{gardenRender();gardenResume()})}else gardenResume()},800)}
function gardenError(q,timeout){if(garden.busy)return;gardenPause();garden.busy=true;garden.lives--;garden.remaining[q.id]=q.config?.seconds||15;chime(false);if(garden.lives<=0){modal(`<div class="intro-animal">${animal('bunny')}</div><h2>${t('Mimi cùng em tính lại nhé','Let’s work it out with Mimi')}</h2><p class="worked-example">${esc(hint(q)).replace(/\n/g,'<br>')}</p><p>${t('Em nhận lại 3 mạng, tiếp tục chăm vườn hoa nhé.','Your 3 lives are restored. Keep growing your garden.')}</p>`,()=>{garden.lives=3;garden.busy=false;gardenRender();gardenResume()})}else{modal(`<h2>${timeout?t('Hết giờ câu này rồi','Time is up for this question'):t('Chưa đúng chậu rồi','Not quite the right pot')}</h2><p>${t('Không sao, mình thử lại nhé. Em còn','That’s okay. Try again! You have')} ${garden.lives} ${t('mạng.','lives.')}</p>`,()=>{garden.busy=false;gardenRender();gardenResume()})}}
function gardenFinish(){clearInterval(gardenTimer);garden.active=null;$('#app').innerHTML=`<div class="narrow card garden-finish"><div class="finished-bouquet">${gardenFlower(true,0)}${gardenFlower(true,1)}${gardenFlower(true,2)}</div><span class="eyebrow">${t('KHU VƯỜN ĐÃ NỞ HOA','YOUR GARDEN IS IN BLOOM')}</span><h1>${t('Em đã làm được rồi!','You did it!')}</h1><p>${t('Đã ôn đúng','Reviewed')} <b>${garden.done.size}</b> ${t('câu từng làm sai. Một khu vườn nhỏ, một bước tiến lớn.','previously missed questions. A little garden, a big step forward.')}</p><p class="reward-label">${t('Mảnh khám phá đã được thêm vào hộ chiếu.','Your discovery pieces have been added to your passport.')}</p><div class="actions"><button class="primary" onclick="nav('setup')">${t('Luyện lượt mới','Practice again')}</button><button onclick="nav('atlas')">${t('Mở hộ chiếu','Open passport')}</button></div></div>`;translate()}
const navBeforeGarden=nav;nav=function(v){if(view==='garden'&&session&&!session.done){if(!confirm(t('Rời vườn hoa? Những câu đã ôn đúng vẫn được lưu.','Leave the garden? Completed matches will remain saved.')))return;session.done=true}if(view==='garden'){clearInterval(gardenTimer);gardenGhost?.remove();gardenGhost=null}navBeforeGarden(v)};
function home(){const pending=state.mistakes.length,companion=buddy(),name=({lion:'Leo',bunny:'Mimi',panda:'Bamboo',fox:'Finn'})[companion]||'Leo';$('#app').innerHTML=`<section class="playground"><div class="playground-hello"><div class="hello-friend">${animal(companion)}<div class="speech-bubble"><span>${t('Chào','Hello')}, ${welcomeName()}!</span><b>${t('Chơi cùng','Come play with')} ${name} ${t('nhé!','today!')}</b></div></div><button class="little-passport" onclick="nav('atlas')"><span class="passport-mini">${t('Của em','My book')}</span><b>${totalPieces()}</b><small>${t('mảnh ghép','pieces')}</small></button></div><div class="playground-title"><h1>${t('Hôm nay, mình đi đâu?','Where shall we play?')}</h1><p>${t('Chạm vào nơi em muốn đến nhé!','Tap a place to start your adventure!')}</p></div>${pending?`<button class="flower-invitation" onclick="startReview()"><span class="invitation-flower">${gardenFlower(false,0)}</span><span><b>${t('Vườn hoa đang chờ em!','Your flowers are waiting!')}</b><small>${pending} ${t('câu mình cùng ôn lại nhé.','questions to grow together.')}</small></span><span class="invitation-arrow">→</span></button>`:''}<div class="playground-map"><div class="play-cloud cloud-one"></div><div class="play-cloud cloud-two"></div><div class="playground-trail"></div><button class="play-place school-place" onclick="nav('setup')"><span class="place-mascot">${animal('lion')}</span><img src="data:image/svg+xml;base64," width="360" height="330" alt="${t('Ngôi nhà học toán của sư tử Leo','Leo’s little math school')}"><span class="place-sign"><b>${t('Học cùng Leo','Learn with Leo')}</b><small>${t('Cộng · Trừ · Nhân · Chia','Add · Subtract · Multiply · Divide')}</small></span></button><button class="play-place race-place" onclick="nav('battleSetup')"><span class="place-mascot">${animal('fox')}</span><img src="data:image/svg+xml;base64," width="360" height="330" alt="${t('Đường đua tính nhẩm cùng các bạn máy','A little math race with bot friends')}"><span class="place-sign"><b>${t('Đua cùng Finn','Race with Finn')}</b><small>${t('Thi vui với các bạn máy','A friendly race with bots')}</small></span></button><button class="play-place world-place" onclick="nav('atlas')"><span class="place-mascot">${animal('panda')}</span><img src="data:image/svg+xml;base64," width="360" height="330" alt="${t('Quả địa cầu và hộ chiếu khám phá','A globe and a discovery passport')}"><span class="place-sign"><b>${t('Đi khám phá','Explore the world')}</b><small>${t('Mở những mảnh ghép mới','Find your next discovery piece')}</small></span></button><div class="play-bush bush-one"></div><div class="play-bush bush-two"></div></div><section class="pick-friend"><div><h2>${t('Ai sẽ đi cùng em?','Who’s coming with you?')}</h2><p>${t('Chạm để chọn bạn đồng hành.','Tap to pick your little buddy.')}</p></div><div class="play-buddies">${buddies.map(([k,n])=>`<button data-buddy="${k}" aria-label="${t('Chọn','Choose')} ${n}" aria-pressed="${companion===k}" class="${companion===k?'chosen':''}"><span>${animal(k)}</span><b>${n}</b>${companion===k?'<small class="buddy-tick">✓</small>':''}</button>`).join('')}</div></section><div class="small-grownup-link"><button onclick="nav('stats')">${t('Xem hành trình của em','See your journey')} →</button><span>${t('Tiến độ được giữ trên máy này.','Your progress stays on this device.')}</span></div></section>`;$$('[data-buddy]').forEach(b=>b.onclick=()=>{state.buddy=b.dataset.buddy;save();home()});translate()}
function setup(){if(state.mistakes.length){$('#app').innerHTML=`<div class="narrow card"><div class="intro-animal">${animal(buddy())}</div><h2>${t('Cùng chăm những chậu hoa còn lại nhé!','Let’s help the remaining flowers bloom!')}</h2><p>${state.mistakes.length} ${t('câu cần ôn. Sai bao nhiêu câu, mình ghép bấy nhiêu chậu.','questions to review. Each missed question gets its own pot.')}</p><button class="primary wide" onclick="startReview()">${t('Vào vườn hoa','Visit the flower garden')}</button></div>`;return}const chosenTypes=config.types||[config.type||'natural'],chosenDigits=config.digits||[1];$('#app').innerHTML=`<div class="narrow"><div class="guide-bubble">${animal(buddy())}<div><b>${t('Mình chọn bài rồi cùng học nhé!','Pick your questions and let’s learn!')}</b><p>${t('Có thể chọn nhiều ô trong mỗi nhóm.','You can choose more than one option in each group.')}</p></div></div><form id="config" class="card lesson-settings"><fieldset><legend><span>1</span>${t('Em muốn tính gì?','What shall we practice?')}</legend><div class="checks operation-picks">${['+','−','×','÷'].map((symbol,i)=>`<label><input type="checkbox" name="op" value="${['+','-','*','/'][i]}" ${config.ops.includes(['+','-','*','/'][i])?'checked':''}><span>${symbol}</span></label>`).join('')}</div></fieldset><fieldset><legend><span>2</span>${t('Chọn loại số','Choose number types')}</legend><p class="settings-hint">${t('Chọn một hoặc nhiều loại để trộn câu hỏi.','Choose one or more to mix question types.')}</p><div class="type-picks">${[['natural','Số tự nhiên','Whole numbers'],['negative','Số âm','Negative numbers'],['decimal','Số thập phân','Decimals'],['fraction','Phân số','Fractions'],['remainder','Chia có dư','Division with remainders']].map(([key,vi,en])=>`<label><input type="checkbox" name="type" value="${key}" ${chosenTypes.includes(key)?'checked':''}><span>${t(vi,en)}</span></label>`).join('')}</div></fieldset><fieldset><legend><span>3</span>${t('Số có mấy chữ số?','How many digits?')}</legend><p class="settings-hint">${t('Chọn 2 nghĩa là số từ 10 đến 99. Chọn nhiều ô để trộn độ dài hai số.','Choose 2 for numbers from 10 to 99. Choose several to mix the lengths of both numbers.')}</p><div class="digit-picks">${[1,2,3,4,5,6].map(n=>`<label><input type="checkbox" name="digits" value="${n}" ${chosenDigits.includes(n)?'checked':''}><span>${n}</span></label>`).join('')}<button id="randomDigits" type="button">${t('Ngẫu nhiên 1–6','Random 1–6')}</button></div><p class="settings-hint small">${t('Thập phân: tính chữ số ở phần nguyên. Phân số: tính chữ số của tử số. Chia có dư luôn dùng phép chia.','Decimals: digits in the whole-number part. Fractions: digits in the numerator. Remainder questions always use division.')}</p></fieldset><fieldset class="session-size"><legend><span>4</span>${t('Mình luyện bao lâu?','How much shall we practice?')}</legend><div class="formgrid"><div><label for="lessonCount">${t('Số câu trong lượt luyện','Questions per session')}</label><div class="chip-row">${[5,10,20,30].map(n=>`<button type="button" data-count="${n}">${n}</button>`).join('')}</div><input id="lessonCount" name="count" type="number" min="1" max="100" value="${config.count||10}" required inputmode="numeric" aria-describedby="countHelp"><small id="countHelp">${t('Chọn nhanh hoặc nhập từ 1–100 câu.','Pick above or enter 1–100 questions.')}</small></div><div><label for="lessonSeconds">${t('Số giây mỗi câu','Seconds per question')}</label><div class="chip-row">${[10,15,30,60].map(n=>`<button type="button" data-seconds="${n}">${n}s</button>`).join('')}</div><input id="lessonSeconds" name="seconds" type="number" min="5" max="120" value="${config.seconds||15}" required inputmode="numeric" aria-describedby="secondsHelp"><small id="secondsHelp">${t('Chọn nhanh hoặc nhập từ 5–120 giây.','Pick above or enter 5–120 seconds.')}</small></div></div></fieldset><div id="lessonSummary" class="lesson-summary" aria-live="polite"></div><button type="submit" class="primary wide">${t('Bắt đầu học','Let’s start')} →</button><p class="settings-hint small">${t('Câu sai tự vào vườn hoa. Không cần chọn số chậu.','Missed questions automatically become flower pots. No pot settings needed.')}</p></form></div>`;const form=$('#config');function refresh(){const f=new FormData(form),count=+f.get('count'),seconds=+f.get('seconds'),digits=f.getAll('digits'),types=f.getAll('type'),ops=f.getAll('op');$$('[data-count]').forEach(b=>b.classList.toggle('chosen',+b.dataset.count===count));$$('[data-seconds]').forEach(b=>b.classList.toggle('chosen',+b.dataset.seconds===seconds));$('#randomDigits').classList.toggle('chosen',digits.length===6);$('#lessonSummary').textContent=`${count} ${t('câu','questions')} · ${seconds}s/${t('câu','question')} · ${digits.length?digits.join(', ')+' '+t('chữ số','digits'):t('Chưa chọn chữ số','Choose digits')} · ${types.length} ${t('loại số','number types')}`;if(ops.length===0)$('#lessonSummary').textContent+=' · '+t('Hãy chọn phép tính','Choose an operation')};form.oninput=refresh;form.onchange=refresh;$$('[data-count]').forEach(b=>b.onclick=()=>{$('#lessonCount').value=b.dataset.count;refresh()});$$('[data-seconds]').forEach(b=>b.onclick=()=>{$('#lessonSeconds').value=b.dataset.seconds;refresh()});$('#randomDigits').onclick=()=>{$$('[name=digits]').forEach(x=>x.checked=true);refresh()};form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),ops=f.getAll('op'),types=f.getAll('type'),digits=f.getAll('digits').map(Number);if(!ops.length||!types.length||!digits.length){toast(t('Chọn ít nhất một phép tính, loại số và số chữ số nhé.','Choose at least one operation, number type and digit length.'));return}config={...defaults,ops,types,digits,count:+f.get('count'),seconds:+f.get('seconds')};startQuiz()};refresh()}
function generate(c=config){const type=pick(c.types?.length?c.types:[c.type||'natural']),digits=c.digits?.length?c.digits:null;let d1=digits?pick(digits):c.d1||1,d2=digits?pick(digits):c.d2||1;d1=Math.min(6,Math.max(1,d1));d2=Math.min(6,Math.max(1,d2));const range=d=>[10**(d-1),10**d-1],number=d=>ri(...range(d));let a=number(d1),b=number(d2),op=type==='remainder'?'/':pick(c.ops),answer,q,options=[];const sym={'+':'+','-':'−','*':'×','/':'÷'}[op];if(type==='fraction'){const da=ri(2,12),db=ri(2,12);let n,d;if(op==='+'){n=a*db+b*da;d=da*db}else if(op==='-'){n=a*db-b*da;d=da*db}else if(op==='*'){n=a*b;d=da*db}else{n=a*db;d=da*b}answer=frac(n,d);q=`${a}/${da} ${sym} ${b}/${db}`;options=[answer];for(let i=1;options.length<4;i++){const v=frac(n+i,d);if(!options.includes(v))options.push(v)}}else if(type==='remainder'){if(d1<d2){[d1,d2]=[d2,d1];[a,b]=[b,a]}b=Math.max(2,Math.min(b,10**d1-2));a=Math.max(a,b+1);if(a%b===0){if(a<10**d1-1)a++;else a--}const quotient=Math.floor(a/b),r=a%b;answer=`${quotient} ${t('dư','r')} ${r}`;q=`${a} ÷ ${b}`;options=[answer,`${quotient+1} ${t('dư','r')} ${r}`,`${quotient} ${t('dư','r')} ${r+1}`,`${quotient+2} ${t('dư','r')} 0`]}else{if(op==='/'){if(d1<d2)[d1,d2]=[d2,d1];const [lo,hi]=range(d1);b=number(d2);const low=Math.max(1,Math.ceil(lo/b)),high=Math.floor(hi/b);a=b*ri(low,high);if(type==='decimal'){// Decimal division by a power of ten has an exact finite answer.
 b=10**(d2-1);a=number(d1)+ri(1,9)/10;
 }}else if(type==='decimal'){a+=ri(1,9)/10;b+=ri(1,9)/10}if(type==='negative'){a=-a;if(Math.random()<.5)b=-b}if(op==='-'&&type==='natural'&&a<b)[a,b]=[b,a];const val=op==='+'?a+b:op==='-'?a-b:op==='*'?a*b:a/b;const display=n=>{const precision=type==='decimal'?(op==='/'?Math.max(4,d2):op==='*'?2:1):0;return Number(n.toFixed(precision)).toLocaleString(lang==='vi'?'vi-VN':'en-US',{useGrouping:false,maximumFractionDigits:precision})};answer=display(val);const operand=n=>n<0?'('+display(n)+')':display(n);q=`${operand(a)} ${sym} ${operand(b)}`;options=[answer];while(options.length<4){const other=display(val+pick([-1,1])*ri(1,12)*(type==='decimal'?.1:1));if(!options.includes(other))options.push(other)}}return {id:crypto.randomUUID(),q,answer,options:shuffle(options),skill:type+':'+op,config:{...c,type},explanation:`${q} = ${answer}`}}
initializeZoo();
